import {mkdir,writeFile} from 'node:fs/promises';
import {join,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {tsImport} from 'tsx/esm/api';
const root=fileURLToPath(new URL('../',import.meta.url));
/**
 * The canonical vectors of the two motion controllers (R4-A §5.3): a configuration, a scripted sequence of setpoints and drive feedback (enable, run, loss, fault), and the commands and events
 * the specification gives for each step. Any other implementation (Python in the agent, C on a microcontroller) must reproduce them exactly. Generated by running the TypeScript reference.
 */
export async function generateControllerVectors(outDir){
 const {diffDriveBaseV1}=await tsImport('../packages/lab-runtime/src/v2/control/diff-drive-base.ts',import.meta.url);
 const {jointTrajectoryFollowerV1}=await tsImport('../packages/lab-runtime/src/v2/control/joint-follower.ts',import.meta.url);
 const wheels=['amr-1/wheel-left','amr-1/wheel-right'],joints=['arm-1/J1','arm-1/J2','arm-1/J3'],grip='arm-1/gripper';
 const fb=(ids,state,positions,velocities,fault=null,over={})=>ids.map((axisId,i)=>({axisId,state:typeof state==='function'?state(axisId):state,fault:(typeof state==='function'?state(axisId):state)==='fault'?fault:null,commandSeq:0,positionRad:positions[i],velocityRadS:velocities[i],torqueNm:0,tick:0,...over}));
 const q=2*Math.PI/1024,round=x=>Math.round(x/q)*q;
 const run=(controller,config,inputs)=>{let s=controller.init(config);return inputs.map(input=>{const r=controller.step(s,input);s=r.state;return {input,expected:{commands:r.commands,events:r.events}};});};
 // ---- diff-drive-base-v1 ----
 const base={axisLeft:wheels[0],axisRight:wheels[1],wheelRadiusM:0.09,wheelSeparationM:0.36,maxWheelAccelRadS2:20,enableTimeoutTicks:6,trackingDegradedRadS:1,trackingDegradedTicks:10};
 const runCase=(()=>{const inputs=[];let angle=[0,0],vel=[0,0],targets=[0,0];
  for(let k=0;k<70;k++){
   const state=k<2?'disabled':k<4?'ready':k<50?'enabled':'fault',sp=k<30?{vMps:0.3,omegaRadps:0.2}:{vMps:0,omegaRadps:0};
   if(state==='enabled')vel=targets;
   angle=angle.map((a,i)=>a+vel[i]*0.02);
   inputs.push({tick:k,setpoint:sp,feedback:fb(wheels,state,angle.map(round),vel,'EXTERNAL_TRIP')});
   // the controller's own next targets feed the next measured speeds
   targets=state==='enabled'?targetsAfter(inputs.length-1):[0,0];
  }
  function targetsAfter(n){let s=diffDriveBaseV1.init(base),out=[0,0];for(let i=0;i<=n;i++){const r=diffDriveBaseV1.step(s,inputs[i]);s=r.state;out=r.commands.map(c=>c.target);}return out;}
  return inputs;})();
 const notReady=Array.from({length:12},(_,k)=>({tick:k,setpoint:{vMps:0.3,omegaRadps:0},feedback:fb(wheels,k<9?'disabled':'ready',[0,0],[0,0])}));
 const rest=Array.from({length:40},(_,k)=>({tick:k,setpoint:{vMps:0,omegaRadps:0},feedback:fb(wheels,'enabled',[k%7===3?q:0,0],[k%7===3?q/0.01:k%7===4?-q/0.01:0,0])}));
 const stuck=Array.from({length:30},(_,k)=>({tick:k,setpoint:{vMps:0.18,omegaRadps:0},feedback:fb(wheels,'enabled',[0,0],[0,0])}));
 // an interlock asks for zero at once: the wheels go to 0 in one tick, not down the acceleration ramp
 const stopNow=(()=>{const inputs=[];let angle=[0,0],vel=[0,0],targets=[0,0];for(let k=0;k<30;k++){const sp=k<15?{vMps:0.3,omegaRadps:0}:{vMps:0,omegaRadps:0,stop:true};if(k>=3)vel=targets;angle=angle.map((a,i)=>a+vel[i]*0.02);inputs.push({tick:k,setpoint:sp,feedback:fb(wheels,k<3?'disabled':'enabled',angle.map(round),vel,null)});let s=diffDriveBaseV1.init(base),out=[0,0];for(const x of inputs){const r=diffDriveBaseV1.step(s,x);s=r.state;out=r.commands.map(c=>c.target);}targets=out;}return inputs;})();
 const diff={schemaVersion:1,controller:{id:diffDriveBaseV1.id,revision:diffDriveBaseV1.revision},generator:'scripts/generate-controller-vectors.mjs',cases:[
  {name:'enable-run-stop-fault',config:base,steps:run(diffDriveBaseV1,base,runCase)},{name:'never-enabled',config:base,steps:run(diffDriveBaseV1,base,notReady)},
  {name:'quantised-encoder-at-rest',config:base,steps:run(diffDriveBaseV1,base,rest)},{name:'wheels-do-not-follow',config:base,steps:run(diffDriveBaseV1,base,stuck)},{name:'stop-now-ignores-the-acceleration-limit',config:base,steps:run(diffDriveBaseV1,base,stopNow)}]};
 // ---- joint-trajectory-follower-v1 ----
 const cfg={axes:joints,gripperAxis:grip,gripperMap:{loRad:0,hiRad:0.85,openingMaxM:0.0889},enableTimeoutTicks:5,followTolRad:0.05,followTicks:6};
 const ids=[...joints,grip];
 const traj=Array.from({length:60},(_,k)=>{const state=k<2?'disabled':k<45?'enabled':id=>id==='arm-1/J2'?'fault':'enabled',target=Math.min(1,0.05*k),pos=[0,1,2].map(i=>round(Math.max(0,target-0.02)*(1+i*0.1))),
   sp={positionsRad:[target,target*1.1,target*1.2],openingM:k<20?0.0889:k<40?0.02:null};
  return {tick:k,setpoint:sp,feedback:fb(ids,state,[...pos,k<22?0.01:0.8],[0,0,0,0],'OVERSPEED')};});
 const follow=Array.from({length:25},(_,k)=>({tick:k,setpoint:{positionsRad:[1,1,1],openingM:0.0889},feedback:fb(ids,'enabled',[0,0,0,0],[0,0,0,0])}));
 const stalled=Array.from({length:12},(_,k)=>({tick:k,setpoint:{positionsRad:[1,1,1],openingM:null},feedback:fb(ids,'disabled',[0.1,0.2,0.3,0.4],[0,0,0,0])}));
 const joint={schemaVersion:1,controller:{id:jointTrajectoryFollowerV1.id,revision:jointTrajectoryFollowerV1.revision},generator:'scripts/generate-controller-vectors.mjs',cases:[
  {name:'enable-follow-grip-fault-hold',config:cfg,steps:run(jointTrajectoryFollowerV1,cfg,traj)},{name:'joints-do-not-follow',config:cfg,steps:run(jointTrajectoryFollowerV1,cfg,follow)},{name:'never-enabled',config:cfg,steps:run(jointTrajectoryFollowerV1,cfg,stalled)}]};
 const files=new Map([['diff-drive-base-v1.vectors.json',diff],['joint-trajectory-follower-v1.vectors.json',joint]]);
 await mkdir(outDir,{recursive:true});
 for(const [name,v] of files)await writeFile(join(outDir,name),JSON.stringify(v)+'\n');
 return [...files.keys()];
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url))await generateControllerVectors(resolve(process.argv[2]??join(root,'tests/fixtures/control')));
